import React, { useState, useEffect } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import Sidebar from './Sidebar';
import { useAuth } from '../../context/AuthContext';

// Preload all dashboard components once user is logged in
// This makes navigation instant - no "Loading..." on tab switches
const preloadDashboardComponents = (userType) => {
  console.log('🚀 Preloading dashboard components for:', userType);

  // Preload based on user type
  if (userType === 'artista') {
    import('../artist/ArtistProfile');
    import('../artist/ArtistPortfolio');
    import('../artist/ArtistProjects');
    import('../artist/ArtistPastProjects');
    import('../artist/ArtistApplications');
    import('../artist/ArtistPricingSettings');
    import('../artist/BrowseProjects');
    import('../artist/ProfileCompletionPrompt');
    import('../artist/ArtistApplicationForm');
  } else if (userType === 'arquiteto') {
    import('../architect/BrowseArtists');
    import('../architect/PostProject');
    import('../architect/ArchitectProjects');
    import('../architect/ArchitectPastProjects');
    import('../architect/Applications');
    import('../loyalty/LoyaltyProgram');
  } else if (userType === 'admin') {
    import('../admin/AdminDashboard');
    import('../admin/ArtistApplicationReview');
    import('../admin/ArtistProfileReview');
  }

  // Preload shared components for all users
  import('../messages/Messages');
  import('../notifications/Notifications');
  import('../shared/ProfileSettings');
  import('../projects/ProjectDetail');

  console.log('✅ All dashboard components preloading...');
};

const DashboardLayout = () => {
  const { profile, signOut, error, loading } = useAuth();
  const navigate = useNavigate();
  const [darkMode, setDarkMode] = useState(false);
  const [componentsPreloaded, setComponentsPreloaded] = useState(false);


  useEffect(() => {
    const savedDarkMode = localStorage.getItem('darkMode');
    if (savedDarkMode !== null) {
      setDarkMode(savedDarkMode === 'true');
    }
  }, []);

  // Preload all dashboard components once profile is loaded
  useEffect(() => {
    if (profile?.user_type && !componentsPreloaded) {
      // Small delay to not interfere with initial page load
      const preloadTimer = setTimeout(() => {
        preloadDashboardComponents(profile.user_type);
        setComponentsPreloaded(true);
      }, 500); // Start preloading after 500ms

      return () => clearTimeout(preloadTimer);
    }
  }, [profile?.user_type, componentsPreloaded]);

  useEffect(() => {
    if (darkMode) {
      document.body.classList.add('dark-mode');
      localStorage.setItem('darkMode', 'true');
    } else {
      document.body.classList.remove('dark-mode');
      localStorage.setItem('darkMode', 'false');
    }
  }, [darkMode]);

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  const handleSignOut = async () => {
    console.log('🔴 Logout button clicked - starting sign out process');
    try {
      console.log('🔴 Calling signOut function...');
      await signOut();
      console.log('✅ SignOut successful, navigating to home...');
      navigate('/', { replace: true });
    } catch (error) {
      console.error('❌ Error signing out:', error);
      // Navigate anyway to ensure user can logout even if API fails
      navigate('/', { replace: true });
    }
  };

  // Show error screen if profile failed to load
  if (error && !loading) {
    return (
      <div className="app-container">
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100vh',
          background: '#f8f9fa'
        }}>
          <div style={{
            maxWidth: '500px',
            padding: '40px',
            background: 'white',
            borderRadius: '12px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
            textAlign: 'center'
          }}>
            <div style={{
              fontSize: '60px',
              marginBottom: '20px'
            }}>⚠️</div>
            <h2 style={{ color: '#dc3545', marginBottom: '15px' }}>Error Loading Profile</h2>
            <p style={{ color: '#666', marginBottom: '30px' }}>{error}</p>
            <button
              onClick={handleSignOut}
              className="btn-primary"
              style={{
                padding: '12px 30px',
                fontSize: '16px',
                background: '#007bff',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              Log In Again
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="app-container">
        <Sidebar
          userType={profile?.user_type}
          onSignOut={handleSignOut}
          darkMode={darkMode}
          toggleDarkMode={toggleDarkMode}
        />

        <main className="main-content">
          <div className="content-wrapper">
            <Outlet />
          </div>
        </main>
      </div>
    </>
  );
};

export default DashboardLayout;
